  ],
  "focus_terms": [
    "current medicines",
    "comorbidity",
    "contraindication",
    "interaction",
    "severity",
    "route",
    "age",
    "already taking"
  ],
  "modules": {
    "patient_evidence": "Extract the stated condition, all current medicines, relevant comorbidities, age/population, severity, and prior therapy response. Mark absent facts as unknown rather than assuming them.",
    "safety_check": "Screen each eligible option against stated comorbidities, current medicines, age, and contraindications. Rank options by avoidance of interactions and disease-specific worsening; do not invent missing facts.",
    "option_selection": "Choose the option that treats the active condition, fits severity and route, avoids the patient's current therapy when change is needed, and has the fewest safety concerns given stated comorbidities and interactions."
  }
}

{
  "diagnosis": "Failures cluster into three mechanisms: (1) indication mismatch — selecting a drug whose mechanism treats a comorbidity or symptom rather than the diagnosed condition, or selecting a same-class drug after prior failure; (2) contraindication/interaction blindness — ignoring prior cancer, allergy history, or current medicines that make an otherwise plausible option unsafe; (3) false-fact inference — treating an unstated or merely suspected diagnosis as confirmed, or assuming a drug is safe because no interaction was explicitly listed.",
  "skills": [
    {
      "id": "indication_first",
      "text": "Before comparing options, restate the working diagnosis and the specific problem being treated. Eliminate any option whose primary indication does not match that problem, even if it treats another condition the patient has. Only then compare the remaining options on safety and patient-specific factors."
    },
    {
      "id": "mechanism_after_failure",
      "text": "If the patient is already taking a drug for the target condition and symptoms are worsening or not improving, prefer an option with a different mechanism of action over another drug in the same class, because same-class agents may share the reason for inadequate response."
    },
    {
      "id": "contraindication_scan",
      "text": "For each candidate option, actively check the patient's stated history (prior cancer, organ disease, pregnancy, allergy/anaphylaxis history) and current medicines for absolute or relative contraindications. A drug that is indicated but contraindicated by a stated fact must be eliminated, not chosen."
    },
    {
      "id": "interaction_check",
      "text": "When a current medicine is named, screen candidate options for known interactions with it (e.g., metabolic-enzyme inhibition, additive toxicity, opposing pharmacodynamics). Prefer an option that treats the diagnosis without a stated interaction over one that has a plausible interaction, and do not assume absence of a listed interaction means safety."
    },
    {
      "id": "no_invented_facts",
      "text": "Treat only explicitly stated patient facts as present. A suspected, rule-out, or 'possible' diagnosis is not confirmed; a symptom mentioned in passing is not a diagnosis; a comorbidity named only as family history does not apply to the patient. Do not use an unstated fact to justify or exclude an option."
    },
    {
      "id": "symptom_vs_diagnosis",
      "text": "Distinguish treating the underlying diagnosed condition from merely relieving a symptom. Choose the option that addresses the diagnosis itself unless the question explicitly asks for symptomatic or prophylactic therapy, in which case match the option to that specific goal."
    }
  ],
  "focus_terms": [
    "indicated for the diagnosed condition",
    "contraindicated by stated history",
    "interacts with current medicine",
    "different mechanism after treatment failure",
    "suspected not confirmed",
    "symptomatic versus disease-modifying"
  ],
  "modules": {
    "patient_evidence": "Extract the working diagnosis, the specific problem being treated, all current medicines, and every stated patient-specific fact (prior cancer, allergy/anaphylaxis history, organ disease, pregnancy). Mark each as confirmed, suspected, or absent; never upgrade a suspected or family-history item to a patient fact.",
    "safety_check": "For every candidate option, check stated contraindications and interactions with current medicines. Eliminate any indicated option that a stated fact makes unsafe. Do not infer safety from the mere absence of a listed interaction.",
    "option_selection": "First filter by indication for the diagnosed problem. Among remaining options, prefer a different mechanism if the patient already failed a same-class drug, then choose the option with the fewest contraindications and interactions. Do not select a drug that only treats a comorbidity or symptom unless the question asks for that."
  }
